function photoThumbs(arr,phase=""){return arr?.length?`<div class="mrp-photo-grid">${arr.map((src,i)=>`<button type="button" class="mrp-photo-btn" data-mrp-zoom="${safe(src)}" aria-label="Reinigungsfoto ${i+1} vergrößern"><img src="${safe(src)}" loading="lazy" alt="Reinigungsfoto ${i+1}"></button>${phase?`<button type="button" class="mrp-photo-remove" data-mrp-remove-photo="${safe(phase)}" data-photo-index="${i}">✕ Foto entfernen</button>`:""}`).join('')}</div>`:''}
function reportsPanel(){const h=state(),sessions=h.sessions,ms=sessions.reduce((a,s)=>a+n(s.durationMs),0),cost=sessions.reduce((a,s)=>a+n(s.materialCost),0),service=h.devices.reduce((a,d)=>a+(d.history||[]).reduce((r,x)=>r+n(x.cost),0),0);
 const byMonth={};for(const s of sessions){const m=s.finishedAt?.slice(0,7)||'Ohne Datum';const v=byMonth[m]||(byMonth[m]={runs:0,ms:0,cost:0});v.runs++;v.ms+=n(s.durationMs);v.cost+=n(s.materialCost)}
 return `<div class="mrp-cards"><div class="mrp-stat"><b>${sessions.length}</b><small>Reinigungen</small></div><div class="mrp-stat"><b>${duration(ms)}</b><small>Arbeitszeit</small></div><div class="mrp-stat"><b>${money(cost)}</b><small>Materialwert (Verbrauch)</small></div><div class="mrp-stat"><b>${money(service)}</b><small>Geräte-Servicekosten</small></div></div><div class="mrp-panel"><div class="mrp-section-head"><h2>Monatsvergleich</h2>${button('export-csv','↓ CSV-Export')}</div>${Object.entries(byMonth).sort((a,b)=>b[0].localeCompare(a[0])).map(([k,v])=>`<div class="mrp-row"><div class="mrp-row-main"><b>${safe(k)}</b><small>${v.runs} Reinigungen · ${duration(v.ms)}</small><div class="mrp-progress"><div style="width:${Math.round(100*v.ms/Math.max(1,...Object.values(byMonth).map(x=>x.ms)))}%"></div></div></div><b>${money(v.cost)}</b></div>`).join('')||hint('Noch keine Statistik vorhanden.')}</div>
 <div class="mrp-panel"><h2>Reinigungsverlauf</h2>${sessions.slice().reverse().slice(0,30).map(x=>`<div class="mrp-row"><div class="mrp-row-main"><b>${safe(formatDate(x.finishedAt?.slice(0,10)))}</b><small>${safe((x.roomIds||[]).map(placeName).join(', '))} · ${duration(x.durationMs)}</small></div>${button('session-detail','Details',x.id)}</div>`).join('')||hint('Erste Reinigung durchführen, um Verlauf zu sehen.')}</div><div class="mrp-notice">Verbrauchskosten sind geschätzte Materialwerte, keine neue Zahlung in den Privatfinanzen. PDF-/Excel-Export und ausführliche Diagramme folgen später.</div>`}
function refresh(){if(!booted||!storage)return;const els=[['mrp-home-root',privateHome],['mrp-today-root',sharedToday],['mrp-household-root',householdShell],['mrp-more-root',privateMore]];for(const [eid,fn] of els){const el=document.getElementById(eid);if(el){if(eid==='mrp-household-root'&&editor==='do-not-refresh')continue;el.innerHTML=fn()}}clock();}
