function field(label,name,val='',typ='text',attrs='',wide=false){return `<div class="mrp-field ${wide?'wide':''}"><label for="mrp-${safe(name)}">${safe(label)}</label><input id="mrp-${safe(name)}" name="${safe(name)}" type="${safe(typ)}" value="${safe(val)}" ${attrs}></div>`}
function selectField(label,name,options,wide=false){return `<div class="mrp-field ${wide?'wide':''}"><label for="mrp-${safe(name)}">${safe(label)}</label><select id="mrp-${safe(name)}" name="${safe(name)}">${options}</select></div>`}
function textField(label,name,val='',wide=true){return `<div class="mrp-field ${wide?'wide':''}"><label for="mrp-${safe(name)}">${safe(label)}</label><textarea id="mrp-${safe(name)}" name="${safe(name)}">${safe(val)}</textarea></div>`}
