 if(kind==='place'){title=editName?'Bereich bearbeiten':'Neues Objekt / Bereich';fields=field('Bezeichnung *','title',obj.name||'','text','required maxlength="100"',true)+selectField('Typ','kind',options(types.map(x=>[x,x]),obj.type||'Objekt'))+selectField('Übergeordneter Bereich','parentId',locChoices(obj.parentId||'',true,obj.id),true)}
