 if(kind==='service'){title='Wartung / Reparatur dokumentieren';fields=field('Datum *','date',dateNow(),'date','required')+selectField('Art','type',options([['Wartung','Wartung'],['Reparatur','Reparatur'],['Reinigung','Reinigung']],'Wartung'))+field('Kosten (€)','cost',0,'number','min="0" step="0.01"')+textField('Durchgeführte Arbeiten / Ersatzteile','note','')}
