function exportCsv(){const h=state();const quoted=v=>'"'+String(v??'').replace(/"/g,'""')+'"';const lines=[['Datum','Räume','Dauer (Minuten)','Aufgaben erledigt','Materialwert (EUR)','Notizen']];for(const s of h.sessions){lines.push([s.finishedAt?.slice(0,10)||'',(s.roomIds||[]).map(pathName).join(' / '),Math.round(n(s.durationMs)/60000),(s.completedTaskIds||[]).length,(n(s.materialCost)).toFixed(2).replace('.',','),s.note||''])}const csv='\ufeff'+lines.map(row=>row.map(quoted).join(';')).join('\r\n');const blob=new Blob([csv],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='MR_Privat_Haushalt_Reinigungen_'+dateNow()+'.csv';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),15000)}
